// A bounded particle system: visual weight comes from layered motion and timing.
export class ImpactFX {
  constructor(ctx,unit,reduced,hit){
    this.ctx=ctx;this.unit=unit;this.reduced=reduced;this.hit=hit;
    this.isMobile=typeof window!=='undefined'&&(matchMedia('(max-width:768px)').matches||('ontouchstart' in window)||navigator.maxTouchPoints>0);
    this.reset();
  }
  reset(){this.clouds=[];this.rocks=[];this.bolts=[];this.orbs=[];this.fields=[];}
  blast(x,y,color,strength=1){if(this.reduced())return;this.clouds.push({x,y,color,strength,age:0,duration:1.15});const count=Math.round((this.isMobile?10:20)*strength);for(let i=0;i<count&&this.rocks.length<(this.isMobile?80:180);i++){const a=Math.random()*Math.PI*2,v=1.5+Math.random()*5;this.rocks.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v-1.5,age:0,duration:.8+Math.random()*.55,size:.04+Math.random()*.09,spin:Math.random()*8,angle:Math.random()*6,color});}this.hit?.(strength);}
  meteor(from,to,color,strength=1,delay=0){if(this.reduced())return;this.orbs.push({from:[from%8+.5,Math.floor(from/8)+.5],to:[to%8+.5,Math.floor(to/8)+.5],color,strength,age:-delay,duration:.3,trail:[]});}
  lightning(a,b,color,strength=1){if(this.reduced())return;const points=[];for(let n=0;n<=20;n++){const t=n/20;points.push([a%8+.5+(b%8-a%8)*t+(n&&n<20?(Math.random()-.5)*.4:0),Math.floor(a/8)+.5+(Math.floor(b/8)-Math.floor(a/8))*t+(n&&n<20?(Math.random()-.5)*.4:0)]);}this.bolts.push({points,color,strength,age:0,duration:.85});this.blast(b%8+.5,Math.floor(b/8)+.5,color,strength*.6);}
  field(x,y,color,strength=1,kind='solar'){if(this.reduced())return;this.fields.push({x,y,color,strength,kind,age:0,duration:1.25});this.blast(x,y,color,strength);}
  draw(now,dt){const u=this.unit(),ctx=this.ctx;if(this.reduced()){this.reset();return;}ctx.save();
    for(const o of this.orbs){o.age+=dt;if(o.age<0)continue;const t=Math.min(1,o.age/o.duration),x=o.from[0]+(o.to[0]-o.from[0])*t,y=o.from[1]+(o.to[1]-o.from[1])*t-Math.sin(t*Math.PI)*1.7;o.trail.unshift([x,y]);o.trail.length=Math.min(o.trail.length,this.isMobile?6:12);ctx.save();ctx.globalCompositeOperation='lighter';for(let i=o.trail.length-1;i>=0;i--){const [tx,ty]=o.trail[i],r=(.17*o.strength)*(1-i/13);ctx.fillStyle=o.color;ctx.globalAlpha=(1-i/13)*.6;if(!this.isMobile){ctx.shadowColor=o.color;ctx.shadowBlur=18;}ctx.beginPath();ctx.arc(tx*u,ty*u,r*u,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;ctx.fillStyle='#fff6d5';ctx.beginPath();ctx.arc(x*u,y*u,.12*o.strength*u,0,Math.PI*2);ctx.fill();ctx.restore();if(t===1){this.blast(o.to[0],o.to[1],o.color,o.strength);o.done=true;}}
    this.orbs=this.orbs.filter(o=>!o.done);
    for(const b of this.bolts){b.age+=dt;const t=b.age/b.duration;ctx.save();ctx.globalCompositeOperation='lighter';ctx.globalAlpha=Math.max(0,(1-t)**.7);ctx.lineJoin='round';ctx.lineCap='round';for(const [width,alpha,color]of [[.25,.22,b.color],[.12,.7,b.color],[.035,1,'#f8fdff']]){ctx.strokeStyle=color;ctx.globalAlpha=Math.max(0,(1-t)*alpha);ctx.lineWidth=u*width*b.strength;if(!this.isMobile){ctx.shadowColor=b.color;ctx.shadowBlur=18;}ctx.beginPath();b.points.forEach(([x,y],i)=>i?ctx.lineTo(x*u,y*u):ctx.moveTo(x*u,y*u));ctx.stroke();}for(let n=3;n<b.points.length-2;n+=5){const [x,y]=b.points[n];ctx.lineWidth=u*.018;ctx.strokeStyle=b.color;ctx.beginPath();ctx.moveTo(x*u,y*u);ctx.lineTo((x+.4)*u,(y-.3)*u);ctx.lineTo((x+.8)*u,(y-.2)*u);ctx.stroke();}ctx.restore();}
    this.bolts=this.bolts.filter(b=>b.age<b.duration);
    for(const f of this.fields){f.age+=dt;const t=f.age/f.duration,rad=(.35+Math.sin(Math.min(1,t)*Math.PI/2)*3.8)*f.strength;ctx.save();ctx.translate(f.x*u,f.y*u);ctx.rotate(t*(f.kind==='lunar'?-1.8:.5));ctx.globalCompositeOperation='lighter';ctx.globalAlpha=Math.max(0,(1-t)*.7);ctx.strokeStyle=f.color;if(!this.isMobile){ctx.shadowColor=f.color;ctx.shadowBlur=22;}ctx.lineWidth=u*.065*(1-t);for(let r=0;r<3;r++){ctx.beginPath();ctx.arc(0,0,Math.max(0,rad-r*.22)*u,0,Math.PI*2);ctx.stroke();}for(let n=0;n<12;n++){const a=n*Math.PI/6;ctx.beginPath();ctx.moveTo(Math.cos(a)*rad*u*.8,Math.sin(a)*rad*u*.8);ctx.lineTo(Math.cos(a)*rad*u,Math.sin(a)*rad*u);ctx.stroke();}ctx.restore();}
    this.fields=this.fields.filter(f=>f.age<f.duration);
    for(const e of this.clouds){e.age+=dt;const t=e.age/e.duration;if(t>=1)continue;const r=(.25+Math.sqrt(t)*1.9)*e.strength*u,x=e.x*u,y=e.y*u;ctx.save();ctx.globalAlpha=(1-t)*.62;const smoke=ctx.createRadialGradient(x,y,r*.2,x,y,r*1.12);smoke.addColorStop(0,'#12202400');smoke.addColorStop(.55,'#28302ae0');smoke.addColorStop(.78,'#1c24297a');smoke.addColorStop(1,'#081b2000');ctx.fillStyle=smoke;ctx.beginPath();ctx.arc(x,y,r*1.12,0,Math.PI*2);ctx.fill();ctx.globalCompositeOperation='lighter';ctx.globalAlpha=(1-t)**1.5;const fire=ctx.createRadialGradient(x,y,0,x,y,r*.75);fire.addColorStop(0,'#ffffe9');fire.addColorStop(.16,'#fff0bd');fire.addColorStop(.42,e.color);fire.addColorStop(1,e.color+'00');ctx.fillStyle=fire;ctx.beginPath();ctx.arc(x,y,r*.75,0,Math.PI*2);ctx.fill();ctx.strokeStyle=e.color;ctx.lineWidth=(.12*(1-t)+.01)*u;if(!this.isMobile){ctx.shadowColor=e.color;ctx.shadowBlur=14;}ctx.beginPath();ctx.ellipse(x,y,r,r*.6,0,0,Math.PI*2);ctx.stroke();ctx.restore();}
    this.clouds=this.clouds.filter(e=>e.age<e.duration).slice(-24);
    for(const p of this.rocks){p.age+=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=9*dt;p.angle+=p.spin*dt;ctx.save();ctx.translate(p.x*u,p.y*u);ctx.rotate(p.angle);ctx.globalAlpha=Math.max(0,1-p.age/p.duration);ctx.fillStyle='#182423';ctx.strokeStyle=p.color;ctx.lineWidth=1.1;ctx.beginPath();ctx.moveTo(-p.size*u,0);ctx.lineTo(0,-p.size*u*.65);ctx.lineTo(p.size*u*.7,p.size*u*.4);ctx.closePath();ctx.fill();ctx.stroke();ctx.restore();}this.rocks=this.rocks.filter(p=>p.age<p.duration);ctx.restore();
  }
}
